<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Image Thumbnail Generator','description'=>'Create a smaller thumbnail from any image directly in your browser.','url'=>'https://smarttoolz.in/tools/image-thumbnail-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Image Thumbnail Generator</h1><p>Create a thumbnail at your chosen width.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="image/*"><label>Width<input id="w" type="number" value="300" min="20" max="3000"></label><button id="go" class="tool-btn">Create Thumbnail</button><a id="d" class="tool-btn" hidden download="thumbnail.jpg">Download Thumbnail</a></div></section></main><script>go.onclick=()=>{let f=document.getElementById('f').files[0];if(!f)return;let i=new Image;i.onload=()=>{let c=document.createElement('canvas'),W=+w.value,H=Math.round(i.height*W/i.width);c.width=W;c.height=H;c.getContext('2d').drawImage(i,0,0,W,H);c.toBlob(b=>{d.href=URL.createObjectURL(b);d.hidden=false},'image/jpeg',.85)};i.src=URL.createObjectURL(f)}</script><?php smarttoolz_tool_page_end(); ?>